      'New password': 'كلمة مرور جديدة', 'Show password': 'إظهار كلمة المرور', 'Hide password': 'إخفاء كلمة المرور', 'Use at least 8 characters.': 'استخدم 8 أحرف على الأقل.',
      'Confirm password': 'تأكيد كلمة المرور', 'Save password': 'حفظ كلمة المرور', 'or': 'أو', 'Continue with Google': 'المتابعة باستخدام Google', 'Continue with Microsoft': 'المتابعة باستخدام Microsoft',
